'use strict';
(()=>{
 const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const urls={uk:'https://forum.russia.online/threads/ugolovnyi-kodeks-ro.39487/',upk:'https://forum.russia.online/threads/ugolovno-protsessual-nyi-kodeks-ro.39485/',koap:'https://forum.russia.online/threads/kodeks-ob-administrativnykh-pravonarusheniyakh-ro.39488/'};
 let data={articles:[],documents:[]},ext={index:[],popular:[],quiz:[]},refs={upkIndex:[],admin:[],adminIndex:[],fsb:[],upk:[],labor:[]},catalog=[],cheats=[],general={},fav=read('arb-favorites',[]),history=read('arb-history',[]),topic=read('arb-topic','all'),at=0,score=0,answered=false;
 function read(k,base){try{return JSON.parse(localStorage.getItem(k))??base}catch{return base}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Не удалось сохранить настройки')}}function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}
 const topicNames={all:'Все темы',officer:'Сотрудник',detain:'Задержание',person:'Личность',service:'Должностные',justice:'Правосудие',public:'Безопасность',military:'Военная служба',property:'Имущество',drugs:'Наркотики',weapons:'Оружие',territory:'Территории',admin:'КоАП'};
 function group(x){let n=x.number;if(['317','318','319','319.3'].includes(n))return 'officer';if(['319.1','319.2','314'].includes(n))return 'detain';if(['314','314.2'].includes(n))return 'detain';if(['228','228.1','231'].includes(n))return 'drugs';if(['222','222.3','226'].includes(n))return 'weapons';if(['139','213','213.1'].includes(n))return 'territory';let v=parseFloat(n);if(v>=331)return 'military';if(v>=294&&v<=316)return 'justice';if(v>=278&&v<=293)return 'service';if(v>=205&&v<278)return 'public';if(v>=158&&v<205)return 'property';return 'person'}
 function rows(){return [...[...ext.popular,...catalog].map(x=>({...x,group:group(x),code:'УК',id:'p'+x.number+'-'+x.part})),...refs.admin.map(x=>({...x,group:'admin',code:'КоАП',id:'adm'+x.number,part:'',stars:null,other:'',admin:true}))]}
 function get(id){let x=rows().find(x=>x.id===id)||data.documents.find(x=>x.id===id)||data.articles.find(x=>x.id===id);if(!x && /^a/.test(id)){let n=id.slice(1);x=rows().find(x=>x.number===n)}return x}
 function favorite(id){fav=fav.includes(id)?fav.filter(x=>x!==id):[...fav,id];save('arb-favorites',fav);renderSaved();renderDocs();renderTables();renderAdmin()}function remember(id){history=[id,...history.filter(x=>x!==id)].slice(0,10);save('arb-history',history);renderSaved()}
 function action(id){return `<button class="star-btn" data-fav="${esc(id)}" aria-pressed="${fav.includes(id)}" aria-label="${fav.includes(id)?'Убрать из избранного':'В избранное'}">${fav.includes(id)?'★':'☆'}</button>`}
 function table(data,target){$(target).innerHTML=data.map(x=>{let star=x.admin||x.stars===null?'—':x.stars===0?(x.starsText||'★–★★★★★'):'★'.repeat(x.stars);let term=x.admin?`Штраф ${x.term}`:`${x.term}${x.number==='314'||x.formula||x.fineOnly?'':' лишения свободы'}`;return `<article class="table-row"><div class="row-code"><span>${esc(x.code)} · ${esc(x.number)}</span>${x.part?`<small>часть ${esc(x.part)}</small>`:''}${x.jurisdiction?`<small>${esc(x.jurisdiction)}</small>`:''}</div><div class="row-title">${esc(x.title)}</div><div class="row-stars" aria-label="${x.admin?'КоАП, без звёзд':esc(star)}">${esc(star)}</div><div class="row-penalty">${esc(term)}${x.other?`<small>${esc(x.other)}</small>`:''}</div><div class="row-actions">${action(x.id)}<a href="${esc(x.url)}" data-open="${esc(x.id)}" target="_blank" rel="noopener" aria-label="Открыть источник">↗</a></div></article>`}).join('')||'<p class="empty">Ничего не найдено. Попробуйте другой запрос.</p>'}
 function renderTables(){let q=$('#popular-search').value.toLocaleLowerCase('ru').trim();table(rows().filter(x=>!x.catalog).filter(x=>[x.number,x.title,x.part,x.code].join(' ').toLocaleLowerCase('ru').includes(q)),'#popular-list');let query=$('#quick-search').value.toLocaleLowerCase('ru').trim();let filtered=rows().filter(x=>(topic==='all'||x.group===topic)&&[x.number,x.part,x.title,x.other,x.code,x.term].join(' ').toLocaleLowerCase('ru').includes(query));table(filtered,'#quick-list');$('#quick-title').textContent=topicNames[topic]||topicNames.all;$('#quick-count').textContent=`${filtered.length} записей · сверка 28.10.2026`;$('#topics').innerHTML=Object.entries(topicNames).map(([id,name],i)=>`<button class="topic-node ${topic===id?'active':''}" data-topic="${id}" aria-pressed="${topic===id}"><i></i><span>${name}</span><small>${id==='all'?rows().length:rows().filter(x=>x.group===id).length}</small></button>`).join('')}
 function renderDocs(){let f=$('#doc-filter').value;$('#documents-list').innerHTML=data.documents.filter(d=>f==='all'||d.category===f).map(d=>`<article class="doc-row"><span class="tag">${esc(d.category)}</span><div><h3>${esc(d.title)}</h3><p>${esc(d.summary)}</p><small>${esc(d.status)} · каталог проверен ${esc(d.checked)}</small></div><div class="doc-actions">${action(d.id)}<a href="${esc(d.url)}" data-open="${esc(d.id)}" target="_blank" rel="noopener">Форум ↗</a></div></article>`).join('')}
 function index(list,query,target,source){let q=$(query).value.trim().toLocaleLowerCase('ru'),out=list.filter(x=>(x.number+' '+x.title).toLocaleLowerCase('ru').includes(q));if(target==='#uk-list'){$(target).innerHTML=out.map(x=>{let parts=rows().filter(z=>z.code==='УК'&&z.number===x.number);let summary=general[x.number];return `<details class="index-entry"><summary><b>${esc(x.number)}</b><span>${esc(x.title)}</span><span>＋</span></summary><div class="index-detail">${summary?'<p>'+esc(summary)+'</p>':''}${parts.length?parts.map(z=>{let star=z.stars===null?'без звёзд':z.stars===0?(z.starsText||'★–★★★★★'):'★'.repeat(z.stars);return `<p><b>${z.part?'Часть '+esc(z.part):'Статья целиком'}</b> · <span class="row-stars">${esc(star)}</span> · ${esc(z.term)}${z.jurisdiction?' · '+esc(z.jurisdiction):''}${z.other?'<br>'+esc(z.other):''}</p>`}).join(''):(summary?'':'<p>Содержание статьи смотрите в первоисточнике.</p>')}<a href="${esc(source)}" target="_blank" rel="noopener">Открыть полный текст ↗</a></div></details>`}).join('')||'<p class="empty">Ничего не найдено.</p>';$('#uk-count').textContent=`${out.length} из ${list.length} статей`}else{$(target).innerHTML=out.map(x=>`<a href="${esc(source)}" target="_blank" rel="noopener"><b>${esc(x.number)}</b><span>${esc(x.title)}</span><span>↗</span></a>`).join('')||'<p class="empty">Ничего не найдено.</p>';if(target==='#admin-index')$('#admin-count').textContent=`${out.length} из ${list.length} пунктов`}}
 function renderCheats(){$('#cheat-list').innerHTML=cheats.map(x=>`<article class="panel cheat-card"><div class="cheat-top"><span>${esc(x.number)} / ПАМЯТКА</span><span>↗</span></div><h2>${esc(x.title)}</h2><p>${esc(x.subtitle)}</p><ol>${x.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.source)} ↗</a></article>`).join('')}
 function renderRef(list,target){$(target).innerHTML=list.map(x=>`<article class="panel"><p class="eyebrow">${esc(x.source)}</p><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p><a href="${esc(x.url)}" target="_blank" rel="noopener">Первоисточник ↗</a></article>`).join('')}
 function renderAdmin(){table(refs.admin.map(x=>({...x,code:'КоАП',id:'adm'+x.number,admin:true})),'#admin-list')}
 function renderSaved(){ $('#fav-count').textContent=fav.length;for(const [el,items,msg] of [['#favorites',fav,'Пока нет избранных материалов.'],['#history',history,'История пока пуста.']])$(el).innerHTML=items.map(id=>{let x=get(id);return x?`<div class="saved-item"><a href="${esc(x.url)}" data-open="${esc(id)}" target="_blank" rel="noopener">${esc(x.code?x.code+' '+x.number+' '+x.title:x.title)} ↗</a>${el==='#favorites'?action(id):''}</div>`:''}).join('')||`<p class="empty">${msg}</p>`}
 function renderSearch(){let q=$('#global-search').value.toLocaleLowerCase('ru').trim();if(!q){$('#search-results').innerHTML='';return}let all=[...ext.index.map(x=>({title:x.title,number:x.number,code:'УК',summary:general[x.number]||'',url:urls.uk})),...refs.upkIndex.map(x=>({title:x.title,number:x.number,code:'УПК',url:urls.upk})),...refs.adminIndex.map(x=>({...x,code:'КоАП',url:urls.koap})),...cheats.map(x=>({title:x.title,summary:x.steps.join(' '),code:'Шпаргалка',url:x.url})),...data.documents.map(x=>({...x,code:x.category}))].filter(x=>[x.title,x.number,x.code,x.summary].filter(Boolean).join(' ').toLocaleLowerCase('ru').includes(q));$('#search-results').innerHTML=all.slice(0,12).map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener"><span>${esc(x.code)} ${esc(x.number||'')}</span><strong>${esc(x.title)}</strong><b>↗</b></a>`).join('')||'<p class="empty">Ничего не найдено в загруженных материалах.</p>'}
 function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function quiz(){answered=false;let q=ext.quiz[at];$('#quiz-feedback').innerHTML='';$('#quiz-next').disabled=true;$('#quiz-next').textContent='Следующий вопрос →';$('#quiz-score').textContent='Верно: '+score;$('#quiz-progress').textContent=`Ситуация ${at+1} / ${ext.quiz.length}`;$('#quiz-bar').style.width=`${at/ext.quiz.length*100}%`;$('#quiz-question').textContent=q.question;$('#quiz-options').innerHTML=shuffle(q.options.map((value,index)=>({value,index}))).map(x=>`<button data-option="${x.index}">${esc(x.value)}</button>`).join('')}
 function route(){let hash=decodeURIComponent(location.hash.slice(1))||'home';let aliases={'uk-index':'uk','articles':'popular','start':'home'};if(hash.startsWith('doc-'))hash='documents';if(hash.startsWith('article-'))hash='popular';hash=aliases[hash]||hash;let active=document.querySelector(`[data-view="${CSS.escape(hash)}"]`);if(!active){hash='home';active=$('[data-view="home"]')}document.querySelectorAll('.view').forEach(v=>v.hidden=v!==active);document.querySelectorAll('#nav a').forEach(a=>{let on=a.getAttribute('href')==='#'+hash;on?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});document.body.classList.toggle('is-quick',hash==='quick');$('#nav').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');window.scrollTo(0,0);document.title=(hash==='home'?'Арбатский':(topicNames[hash]||active.querySelector('h1')?.textContent||'Арбатский'))+' · Правовой портал'}
 function init(){if(!topicNames[topic])topic='all';renderDocs();renderTables();index(ext.index,'#uk-search','#uk-list',urls.uk);index(refs.upkIndex,'#upk-search','#upk-list',urls.upk);renderRef(refs.fsb,'#fsb-content');renderRef(refs.upk,'#upk-highlights');renderRef(refs.labor,'#labor-content');index(refs.adminIndex,'#admin-search','#admin-index',urls.koap);renderCheats();renderAdmin();renderSaved();quiz();$('#loading').hidden=true;route()}
 window.addEventListener('hashchange',route);$('#menu-btn').onclick=()=>{let open=$('#nav').classList.toggle('open');$('#menu-btn').setAttribute('aria-expanded',String(open))};$('#doc-filter').onchange=renderDocs;$('#popular-search').oninput=renderTables;$('#quick-search').oninput=renderTables;$('#uk-search').oninput=()=>index(ext.index,'#uk-search','#uk-list',urls.uk);$('#upk-search').oninput=()=>index(refs.upkIndex,'#upk-search','#upk-list',urls.upk);$('#admin-search').oninput=()=>index(refs.adminIndex,'#admin-search','#admin-index',urls.koap);$('#global-search').oninput=renderSearch;$('#clear-search').onclick=()=>{$('#global-search').value='';renderSearch();$('#global-search').focus()};$('#clear-history').onclick=()=>{history=[];save('arb-history',history);renderSaved()};
 document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}let t=e.target.closest('[data-topic]');if(t){topic=t.dataset.topic;save('arb-topic',topic);renderTables()}let f=e.target.closest('[data-fav]');if(f)favorite(f.dataset.fav);let a=e.target.closest('[data-open]');if(a)remember(a.dataset.open)});
 $('#copy-miranda').onclick=async()=>{let text=$('#miranda-text').textContent;try{await navigator.clipboard.writeText(text);toast('Текст скопирован')}catch{let t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();try{document.execCommand('copy')?toast('Текст скопирован'):toast('Не удалось скопировать')}catch{toast('Не удалось скопировать')}t.remove()}};
 $('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Полный экран недоступен. Попробуйте F11 в браузере.')}};document.addEventListener('fullscreenchange',()=>$('#fullscreen').textContent=document.fullscreenElement?'Выйти из полного экрана ⛶':'На весь экран ⛶');
 $('#quiz-options').onclick=e=>{let b=e.target.closest('[data-option]');if(!b||answered)return;answered=true;let q=ext.quiz[at],good=Number(b.dataset.option)===q.correct;if(good)score++;for(let el of $('#quiz-options').querySelectorAll('button')){el.disabled=true;if(Number(el.dataset.option)===q.correct)el.classList.add('correct');else if(el===b)el.classList.add('incorrect')}$('#quiz-score').textContent='Верно: '+score;$('#quiz-feedback').innerHTML=`<strong>${good?'Верно':'Не совсем'}</strong><p>${esc(q.explanation)}</p><a href="${esc(q.url)}" target="_blank" rel="noopener">${esc(q.source)} ↗</a>`;$('#quiz-next').disabled=false;$('#quiz-next').textContent=at===ext.quiz.length-1?'Показать результат →':'Следующий вопрос →'};$('#quiz-next').onclick=()=>{if(!answered)return;at++;if(at===ext.quiz.length){$('#quiz-progress').textContent='Тест завершён';$('#quiz-bar').style.width='100%';$('#quiz-question').textContent=`Результат: ${score} / ${ext.quiz.length}`;$('#quiz-options').innerHTML='';$('#quiz-feedback').innerHTML='<p>Повторите сложные ситуации и сверьтесь с первоисточником.</p>';$('#quiz-next').disabled=true}else quiz()};$('#quiz-restart').onclick=()=>{at=0;score=0;quiz()};
 Promise.all(['data.json','extended.json','references.json','catalog.json','cheats.json','general.json'].map(p=>fetch('./'+p).then(r=>{if(!r.ok)throw Error(p);return r.json()}))).then(([d,x,r,c,h,g])=>{data=d;ext=x;refs=r;catalog=c;cheats=h;general=g;init()}).catch(()=>{$('#loading').textContent='Не удалось загрузить данные. Проверьте файлы справочника и подключение.'});
})();
